  // Título principal
  doc.setFontSize(26);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(44, 62, 80);
  doc.text("REPORTE TÉCNICO", pageW / 2, 110, null, null, 'center');
  
  doc.setFontSize(14);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(75, 123, 236);
